/* eslint-disable */
export type Maybe<T> = T | null;
export type InputMaybe<T> = Maybe<T>;
/** All built-in and custom scalars, mapped to their actual values */
export type Scalars = {
  ID: { input: string; output: string; }
  String: { input: string; output: string; }
  Boolean: { input: boolean; output: boolean; }
  Int: { input: number; output: number; }
  Float: { input: number; output: number; }
  Date: { input: unknown; output: unknown; }
  DateTime: { input: any; output: any; }
  JSON: { input: any; output: any; }
};

export type Query = {
  __typename?: 'Query';
  /** Return public collections that include the specified item (e.g. downloads are Discussions with hasDownload=true). */
  publicCollectionsContaining: Array<Collection>;
  /**
   * Return albums that contain an image, grouped by whether the album owner is
   * the original image uploader. Uses the existing HAS_IMAGE relationship, which
   * can support multiple albums per image.
   */
  getImageAlbumUsage: ImageAlbumUsage;
  /** Return public setup capabilities without exposing environment values. */
  getInstanceSetupStatus: InstanceSetupStatus;
  getDiscussionsInChannel?: Maybe<DiscussionChannelListFormat>;
  /**
   * Return the bounded data needed for the first discussion/download detail
   * render, scoped to the channel in the route.
   */
  getDiscussionDetail: Array<Discussion>;
  getDiscussionDetailAnswers: DiscussionAnswerPage;
  getDiscussionDetailFiles: DiscussionFilePage;
  getDiscussionDetailImages: DiscussionImagePage;
  getSiteWideDiscussionList?: Maybe<SiteWideDiscussionListFormat>;
  getRankingSettings: RankingSettings;
  getChannelDiscussionFlairConfig: ChannelDiscussionFlairConfig;
  getSiteWideIssueList?: Maybe<SiteWideIssueListFormat>;
  getSiteWideWikiList?: Maybe<SiteWideWikiListFormat>;
  getCommentSection?: Maybe<CommentSectionFormat>;
  getEventComments?: Maybe<EventCommentsFormat>;
  getCommentReplies?: Maybe<CommentRepliesFormat>;
  /**
   * Return the authenticated caller's own account summary, keyed off the
   * verified token email. Self-scoped (takes no arguments), so it cannot look
   * up anyone else. Used by onboarding to detect whether the logged-in user
   * already has an account: returns null when not authenticated, and an object
   * with username: null when authenticated but no account exists yet.
   */
  getOwnEmail?: Maybe<OwnEmail>;
  /** Return the server's public age-gating configuration. */
  getAgePolicy: AgePolicy;
  /** Return only the authenticated caller's private age profile. */
  getMyAgeProfile?: Maybe<OwnAgeProfile>;
  /**
   * Whether a discussion (or download) the viewer can't load is behind the
   * sensitive-content age gate, and what they need to open it. Returns no
   * content, so it's safe to call for restricted viewers.
   */
  getDiscussionAgeGateCheck: AgeGateCheck;
  getUploadedDownloadableFiles: Array<UploadedDownloadableFileGroup>;
  getUserFavoriteComment?: Maybe<Scalars['Boolean']['output']>;
  getSortedChannels?: Maybe<GetSortedChannelsResponse>;
  getUserContributions: Array<DayData>;
  getUserWikiEditsCount: Scalars['Int']['output'];
  getChannelContributions: Array<UserContributionData>;
  getModContributions: Array<ModDayData>;
  getServerHealthDashboard: ServerHealthDashboard;
  getDownloadScanReviewQueue: Array<DownloadScanReviewItem>;
  isOriginalPosterSuspended?: Maybe<Scalars['Boolean']['output']>;
  safetyCheck?: Maybe<SafetyCheckResponse>;
  getServerPluginSecrets: Array<PluginSecretStatus>;
  getPluginConfigStatus: PluginConfigStatus;
  getInstalledPlugins: Array<InstalledPlugin>;
  /** Preview additive server plugin drift without changing live configuration. */
  previewPluginConfigurationReconciliation: PluginConfigurationReconciliationPlan;
  getPluginRunsForDownloadableFile: Array<PluginRun>;
  getPipelineRuns: Array<PluginRun>;
  getApplicablePluginPipeline: ApplicablePluginPipeline;
  getPipelineSummary: PluginPipelineSummary;
  getPublicPipelineRun?: Maybe<PublicPluginPipelineRun>;
  getInternalPluginPipelineRun?: Maybe<InternalPluginPipelineRunDetail>;
  previewPluginPipelineCampaign: PluginPipelineCampaignPreview;
  getPluginPipelineCampaigns: Array<PluginPipelineCampaign>;
  getPluginPipelineCampaignFailures: Array<PluginPipelineCampaignFailure>;
  issueCommentAuthors: Array<IssueCommentAuthor>;
  commentAuthors: Array<CommentAuthor>;
  issueAuthors: Array<IssueAuthor>;
  imagesConnection: ImagesConnection;
  images: Array<Image>;
  licensesConnection: LicensesConnection;
  licenses: Array<License>;
  purchasesConnection: PurchasesConnection;
  purchases: Array<Purchase>;
  fileVersionsConnection: FileVersionsConnection;
  fileVersions: Array<FileVersion>;
  collectionsConnection: CollectionsConnection;
  collections: Array<Collection>;
  albumsConnection: AlbumsConnection;
  albums: Array<Album>;
  notificationsConnection: NotificationsConnection;
  notifications: Array<Notification>;
  messagesConnection: MessagesConnection;
  messages: Array<Message>;
  contactsConnection: ContactsConnection;
  contacts: Array<Contact>;
  usersConnection: UsersConnection;
  users: Array<User>;
  scratchpadEntriesConnection: ScratchpadEntriesConnection;
  scratchpadEntries: Array<ScratchpadEntry>;
  textVersionsConnection: TextVersionsConnection;
  textVersions: Array<TextVersion>;
  labelChangeHistoriesConnection: LabelChangeHistoriesConnection;
  labelChangeHistories: Array<LabelChangeHistory>;
  wikiPageFulltext: WikiPagesIndexConnection;
  wikiPagesConnection: WikiPagesConnection;
  wikiPages: Array<WikiPage>;
  suspensionsConnection: SuspensionsConnection;
  suspensions: Array<Suspension>;
  downloadableFilesConnection: DownloadableFilesConnection;
  downloadableFiles: Array<DownloadableFile>;
  filterGroupsConnection: FilterGroupsConnection;
  filterGroups: Array<FilterGroup>;
  filterOptionsConnection: FilterOptionsConnection;
  filterOptions: Array<FilterOption>;
  channelFulltext: ChannelsIndexConnection;
  channelsConnection: ChannelsConnection;
  channels: Array<Channel>;
  discussionChannelsConnection: DiscussionChannelsConnection;
  discussionChannels: Array<DiscussionChannel>;
  discussionFulltext: DiscussionsIndexConnection;
  discussionsConnection: DiscussionsConnection;
  discussions: Array<Discussion>;
  eventChannelsConnection: EventChannelsConnection;
  eventChannels: Array<EventChannel>;
  repeatPatternsConnection: RepeatPatternsConnection;
  repeatPatterns: Array<RepeatPattern>;
  eventSeriesConnection: EventSeriesConnection;
  eventSeries: Array<EventSeries>;
  recurringEventsConnection: RecurringEventsConnection;
  recurringEvents: Array<RecurringEvent>;
  eventsConnection: EventsConnection;
  events: Array<Event>;
  commentsConnection: CommentsConnection;
  comments: Array<Comment>;
  emojisConnection: EmojisConnection;
  emojis: Array<Emoji>;
  emailsConnection: EmailsConnection;
  emails: Array<Email>;
  moderationProfilesConnection: ModerationProfilesConnection;
  moderationProfiles: Array<ModerationProfile>;
  moderationActionsConnection: ModerationActionsConnection;
  moderationActions: Array<ModerationAction>;
  issueFulltext: IssuesIndexConnection;
  issuesConnection: IssuesConnection;
  issues: Array<Issue>;
  feedsConnection: FeedsConnection;
  feeds: Array<Feed>;
  tagsConnection: TagsConnection;
  tags: Array<Tag>;
  serverRolesConnection: ServerRolesConnection;
  serverRoles: Array<ServerRole>;
  channelRolesConnection: ChannelRolesConnection;
  channelRoles: Array<ChannelRole>;
  modChannelRolesConnection: ModChannelRolesConnection;
  modChannelRoles: Array<ModChannelRole>;
  modServerRolesConnection: ModServerRolesConnection;
  modServerRoles: Array<ModServerRole>;
  pluginsConnection: PluginsConnection;
  plugins: Array<Plugin>;
  pluginVersionsConnection: PluginVersionsConnection;
  pluginVersions: Array<PluginVersion>;
  serverSecretsConnection: ServerSecretsConnection;
  serverSecrets: Array<ServerSecret>;
  pluginPipelineRunsConnection: PluginPipelineRunsConnection;
  pluginPipelineRuns: Array<PluginPipelineRun>;
  pluginPipelineCampaignsConnection: PluginPipelineCampaignsConnection;
  pluginPipelineCampaigns: Array<PluginPipelineCampaign>;
  pluginRunsConnection: PluginRunsConnection;
  pluginRuns: Array<PluginRun>;
  serverConfigsConnection: ServerConfigsConnection;
  serverConfigs: Array<ServerConfig>;
};


